    if rl is not None:
        return rl
    if not API_KEY:
        return _json_error("Missing BigModel API key in environment", 500)
    req_json: Dict[str, Any] = {}
    parsed_files: List[Tuple[str, str]] = []
    search_results: List[Dict[str, Any]] = []
    search_meta: Dict[str, Any] = {"enabled": False}
    trivial = False
