    try:
        req_json, parsed_files, search_results, search_meta, body, trivial = _handle_chat_common(stream=True)
        model_for_log = str(body.get("model") or DEFAULT_MODEL)
    except ValueError as e:
        parsed_meta = [{"name": n, "chars": len(t)} for n, t in parsed_files]
        with suppress(Exception):
            _db_log_chat(model_for_log, req_json, None, None, None, search_results, parsed_meta, str(e), _client_ip(), request.headers.get("User-Agent"), False)
        return _json_error(str(e), 400)
    except Exception as e:
        log.exception("stream init failed")
        parsed_meta = [{"name": n, "chars": len(t)} for n, t in parsed_files]
        with suppress(Exception):
            _db_log_chat(model_for_log, req_json, None, None, None, search_results, parsed_meta, str(e), _client_ip(), request.headers.get("User-Agent"), False)
        return _json_error("Stream request failed", 500, str(e))
    chunk_id = "chatcmpl-" + uuid.uuid4().hex
    model = model_for_log
    remote_addr = _client_ip()
    user_agent = request.headers.get("User-Agent")
    parsed_meta = [{"name": n, "chars": len(t)} for n, t in parsed_files]
    max_acc = _env_int("STREAM_ACC_MAX_CHARS", 400000)
    max_reason = _env_int("STREAM_REASON_MAX_CHARS", 200000)

    def gen() -> Iterable[str]:
        acc_parts: List[str] = []
        reason_parts: List[str] = []
        acc_len = 0
        reason_len = 0
        tool_calls_state: Dict[int, Dict[str, Any]] = {}
        err: Optional[str] = None
        completed = False
        final_fr: Optional[str] = None
        try:
            yield _sse_line({"type": "start", "id": chunk_id, "model": model, "web_search_enabled": bool(search_meta.get("enabled"))})
            timeout = _env_float("CHAT_STREAM_TIMEOUT_TRIVIAL", 45.0) if trivial else _env_float("CHAT_STREAM_TIMEOUT", 300.0)
            raw_lines = _bigmodel_stream_raw("/chat/completions", body, timeout=timeout)
            for item in _parse_sse_data_lines(raw_lines):
                if item == "[DONE]":
                    break
                if not isinstance(item, dict):
                    continue
                delta, finish_reason = _extract_chunk_parts(item)
                out: Dict[str, Any] = {}
                if "content" in delta and delta["content"] is not None:
                    s = str(delta["content"])
                    out["content"] = s
                    if max_acc <= 0 or acc_len + len(s) <= max_acc:
                        acc_parts.append(s)
                        acc_len += len(s)
                if "reasoning_content" in delta and delta["reasoning_content"] is not None:
                    rs = str(delta["reasoning_content"])
                    out["reasoning_content"] = rs
                    if max_reason <= 0 or reason_len + len(rs) <= max_reason:
                        reason_parts.append(rs)
                        reason_len += len(rs)
                if "tool_calls" in delta and delta["tool_calls"] is not None:
                    _merge_stream_tool_calls(tool_calls_state, delta["tool_calls"])
                    out["tool_calls"] = delta["tool_calls"]
                if out:
                    payload: Dict[str, Any] = {"type": "delta", "id": chunk_id}
                    if "content" in out:
                        payload["content"] = out["content"]
                    if "reasoning_content" in out:
                        payload["reasoning"] = out["reasoning_content"]
                    if "tool_calls" in out:
                        payload["tool_calls"] = out["tool_calls"]
                    yield _sse_line(payload)
                if finish_reason is not None:
                    final_fr = finish_reason
            if final_fr is None:
                final_fr = "stop"
            reply_full = "".join(acc_parts)
            reason_full = "".join(reason_parts)
            tool_calls_val = _finalize_stream_tool_calls(tool_calls_state)
            completed = True
            yield _sse_line({"type": "final", "id": chunk_id, "reply": reply_full, "reasoning": reason_full, "tool_calls": tool_calls_val, "finish_reason": final_fr})
            yield _sse_line("[DONE]")
        except GeneratorExit:
            err = "client disconnected"
            raise
        except Exception as e:
            err = str(e)
            yield _sse_line({"type": "error", "id": chunk_id, "message": err})
            yield _sse_line("[DONE]")
        finally:
            reply_full2 = "".join(acc_parts)
            reason_full2 = "".join(reason_parts)
            tool_calls_val2 = _finalize_stream_tool_calls(tool_calls_state)
            with suppress(Exception):
                _db_log_chat(model, req_json, reply_full2, reason_full2, tool_calls_val2, search_results, parsed_meta, err, remote_addr, user_agent, completed)

    resp = Response(stream_with_context(gen()), mimetype="text/event-stream")
    resp.headers["Cache-Control"] = "no-store"
    resp.headers["X-Accel-Buffering"] = "no"
    resp.headers["Connection"] = "keep-alive"
    return resp


def _serve_file(path: str) -> Optional[Response]:
    root = os.path.abspath(os.environ.get("STATIC_ROOT") or os.getcwd())
    target = os.path.abspath(os.path.join(root, path))
    try:
        common = os.path.commonpath([root, target])
    except Exception:
        return None
    if common != root:
        return None
    if os.path.isfile(target):
        directory = os.path.dirname(target)
        filename = os.path.basename(target)
        return send_from_directory(directory, filename)
    return None


